cd /tmp/binlog-reader && cat > Program.cs << 'EOF'
using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check build result
Console.WriteLine($"Build succeeded: {build.Succeeded}");
Console.WriteLine();

// Find all projects and their results
var projects = build.FindChildrenRecursive<Project>();
Console.WriteLine("=== PROJECT BUILD RESULTS ===");
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} - Succeeded: {p.Succeeded}");
}
Console.WriteLine();

// Get source file content from compiler task
var tasks = build.FindChildrenRecursive<Task>();
foreach (var t in tasks)
{
    if (t.Name == "Csc")
    {
        Console.WriteLine($"=== CSC Task in {t.Parent?.Parent} ===");
        var commandLine = t.FindChildrenRecursive<Property>().FirstOrDefault(p => p.Name == "CommandLineArguments");
        if (commandLine != null)
        {
            // Extract source files from command line
            var lines = commandLine.Value.Split(' ');
            var sources = lines.Where(l => l.EndsWith(".cs") && !l.StartsWith("/")).ToList();
            Console.WriteLine($"  Sources: {string.Join(", ", sources)}");
        }
    }
}

// Check if Api project built or was skipped
var messages = build.FindChildrenRecursive<Message>();
var skipMessages = messages.Where(m => m.Text != null && m.Text.Contains("not build")).ToList();
foreach (var m in skipMessages)
{
    Console.WriteLine($"  Skip: {m.Text}");
}

// Find SourceFiles from the embedded content
Console.WriteLine("\n=== LOOKING FOR EMBEDDED SOURCE ===");
var allItems = build.FindChildrenRecursive<Item>();
var sourceItems = allItems.Where(i => i.Name == "Compile" || i.Name == "SourceFile").ToList();
foreach (var item in sourceItems.Take(20))
{
    Console.WriteLine($"  {item.Name}: {item.Text}");
}
EOF
