using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine($"Build succeeded: {build.Succeeded}");
Console.WriteLine();

// Find all projects
var projects = build.FindChildrenRecursive<Project>();
Console.WriteLine("=== PROJECTS ===");
foreach (var p in projects)
{
    var errors = p.FindChildrenRecursive<Error>();
    Console.WriteLine($"  {p.Name} ({p.ProjectFile}) - Errors: {errors.Count}");
}
Console.WriteLine();

// Errors already found
var errors2 = build.FindChildrenRecursive<Error>();
Console.WriteLine($"=== ALL ERRORS ({errors2.Count}) ===");
foreach (var e in errors2)
{
    Console.WriteLine($"  [{e.Code}] {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Text}");
    Console.WriteLine($"    Project: {e.ProjectFile}");
}

// Check for MSB errors in messages  
Console.WriteLine("\n=== MSB MESSAGES ===");
var msgs = build.FindChildrenRecursive<Message>();
var msbErrors = msgs.Where(m => m.Text != null && (m.Text.Contains("MSB3202") || m.Text.Contains("MSB4181") || m.Text.Contains("did not build"))).ToList();
foreach (var m in msbErrors.Take(10))
{
    Console.WriteLine($"  {m.Text}");
}

// Look for the source file content in the SourceContentItems  
Console.WriteLine("\n=== SOURCE CONTENT ===");
var cscTasks = build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc").ToList();
Console.WriteLine($"Csc tasks found: {cscTasks.Count}");
foreach (var csc in cscTasks)
{
    var proj = csc.GetNearestParent<Project>();
    Console.WriteLine($"\n  Project: {proj?.Name}");
    var outputs = csc.FindChildrenRecursive<Item>().ToList();
    Console.WriteLine($"  Items: {outputs.Count}");
}
EOF
