using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Look for the Csc command lines to understand what source files contain
var cscTasks = build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc").ToList();
foreach (var csc in cscTasks)
{
    var proj = csc.GetNearestParent<Project>();
    Console.WriteLine($"=== Csc in {proj?.Name} ===");

    // Get the command line arguments property
    var folder = csc.FindChild<Folder>("Parameters");
    if (folder != null)
    {
        foreach (var child in folder.Children)
        {
            if (child is Property prop && prop.Name == "Sources")
            {
                Console.WriteLine($"  Sources: {prop.Value}");
            }
        }
    }
}

// Check if Api project has any build target that was skipped/failed
Console.WriteLine("\n=== LOOKING FOR API BUILD FAILURE ===");
var targets = build.FindChildrenRecursive<Target>().ToList();
var failedTargets = targets.Where(t => !t.Succeeded).ToList();
Console.WriteLine($"Failed targets: {failedTargets.Count}");
foreach (var t in failedTargets.Take(20))
{
    var proj = t.GetNearestParent<Project>();
    Console.WriteLine($"  Target '{t.Name}' in {proj?.Name} - Succeeded: {t.Succeeded}");
}

// Get source file content from embedded files
Console.WriteLine("\n=== EMBEDDED SOURCE FILES ===");
var sourceFiles = build.SourceFiles;
if (sourceFiles != null)
{
    foreach (var kvp in sourceFiles.Where(k => k.Key.Contains("sv-b2bf201986034dcfbdc483c613d88077") && k.Key.EndsWith(".cs")))
    {
        Console.WriteLine($"\n--- {kvp.Key} ---");
        Console.WriteLine(kvp.Value);
    }
}
EOF
