        {
            if (child is Property prop && prop.Name == "Sources")
            {
                Console.WriteLine($"  Sources: {prop.Value}");
            }
            if (child is Property prop2 && prop2.Name == "References")
            {
                Console.WriteLine($"  References: {prop2.Value}");
            }
        }
    }
    // Also look for the output messages (errors) 
    var msgs = csc.FindChildrenRecursive<Message>().ToList();
    foreach (var m in msgs.Where(x => x.Text != null && x.Text.Contains("error")))
    {
        Console.WriteLine($"  MSG: {m.Text}");
    }
}

