{
    var buildTarget = api.FindChildrenRecursive<Target>()
        .FirstOrDefault(t => t.Name == "Build" && !t.Succeeded);
    if (buildTarget != null)
    {
        Console.WriteLine($"  Build target found, children: {buildTarget.Children.Count}");
        foreach (var child in buildTarget.Children)
        {
            Console.WriteLine($"    Child: {child.GetType().Name} - {child}");
        }
    }
}
