using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Look at the compiler output for Services to understand what's happening
var cscTasks = build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc").ToList();
foreach (var csc in cscTasks)
{
    var proj = csc.GetNearestParent<Project>();
    Console.WriteLine($"=== Csc in {proj?.Name} ===");

    // The compiler output should show us the exact error context
    var output = csc.FindChildrenRecursive<CscTaskItem>().ToList();
    Console.WriteLine($"  CscTaskItem count: {output.Count}");

    // Look at messages for the actual compile output
    var messages = csc.FindChildrenRecursive<Message>().ToList();
    foreach (var m in messages)
    {
        if (m.Text != null && m.Text.Contains("UserService"))
            Console.WriteLine($"  MSG: {m.Text}");
    }
